PRAGMA journal_mode=WAL;
PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS meta(key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY, role TEXT NOT NULL, salt TEXT NOT NULL, password_hash TEXT NOT NULL, enabled INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS tokens(hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), expires REAL NOT NULL);
CREATE TABLE IF NOT EXISTS championships(id TEXT PRIMARY KEY, name TEXT NOT NULL, data_mode TEXT NOT NULL, source TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(id TEXT PRIMARY KEY, championship_id TEXT REFERENCES championships(id), name TEXT NOT NULL, date TEXT, session_start TEXT, source TEXT);
CREATE TABLE IF NOT EXISTS events(id TEXT PRIMARY KEY, session_id TEXT REFERENCES sessions(id), name TEXT NOT NULL, discipline TEXT NOT NULL, gender TEXT NOT NULL, round TEXT NOT NULL, relay INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS heats(id TEXT PRIMARY KEY, event_id TEXT NOT NULL REFERENCES events(id), timing_event INTEGER NOT NULL, timing_heat INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'SCHEDULED', revision INTEGER NOT NULL DEFAULT 0, clock_ticks INTEGER, last_timing REAL, recovery_hold INTEGER NOT NULL DEFAULT 0, published INTEGER NOT NULL DEFAULT 0, UNIQUE(timing_event,timing_heat));
CREATE TABLE IF NOT EXISTS universities(id TEXT PRIMARY KEY, name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS athletes(id TEXT PRIMARY KEY, name TEXT NOT NULL, country TEXT NOT NULL, university_id TEXT NOT NULL REFERENCES universities(id), gender TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS teams(id TEXT PRIMARY KEY, name TEXT NOT NULL, country TEXT NOT NULL, fisu_team INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS relay_members(team_id TEXT REFERENCES teams(id), position INTEGER, athlete_id TEXT REFERENCES athletes(id), PRIMARY KEY(team_id,position));
CREATE TABLE IF NOT EXISTS entries(heat_id TEXT REFERENCES heats(id), lane INTEGER NOT NULL, athlete_id TEXT REFERENCES athletes(id), team_id TEXT REFERENCES teams(id), seed_ticks INTEGER, PRIMARY KEY(heat_id,lane), CHECK((athlete_id IS NULL)!=(team_id IS NULL)), CHECK(lane>=0 AND lane<=12));
CREATE TABLE IF NOT EXISTS raw_messages(id INTEGER PRIMARY KEY AUTOINCREMENT, received REAL NOT NULL, source TEXT NOT NULL, profile TEXT NOT NULL, sequence INTEGER NOT NULL, frame_hex TEXT NOT NULL, parsed TEXT, disposition TEXT NOT NULL, UNIQUE(source,sequence));
CREATE TABLE IF NOT EXISTS timings(id INTEGER PRIMARY KEY AUTOINCREMENT, heat_id TEXT NOT NULL REFERENCES heats(id), lane INTEGER, kind TEXT NOT NULL, touch INTEGER, ticks INTEGER, raw_id INTEGER REFERENCES raw_messages(id), active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS results(heat_id TEXT REFERENCES heats(id), lane INTEGER NOT NULL, ticks INTEGER, rank INTEGER, irm TEXT, qualification TEXT, record TEXT, medal TEXT, source TEXT NOT NULL, reason TEXT NOT NULL, PRIMARY KEY(heat_id,lane));
CREATE TABLE IF NOT EXISTS approvals(id INTEGER PRIMARY KEY AUTOINCREMENT, heat_id TEXT REFERENCES heats(id), revision INTEGER NOT NULL, stage TEXT NOT NULL, user_id TEXT NOT NULL REFERENCES users(id), at REAL NOT NULL, reason TEXT NOT NULL, revoked INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS jury_decisions(id INTEGER PRIMARY KEY AUTOINCREMENT,heat_id TEXT REFERENCES heats(id), user_id TEXT REFERENCES users(id), at REAL NOT NULL, reason TEXT NOT NULL, document_ref TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS routes(output TEXT PRIMARY KEY, content TEXT NOT NULL, template TEXT, heat_id TEXT, safe INTEGER NOT NULL DEFAULT 32, blackout INTEGER NOT NULL DEFAULT 0, playlist TEXT NOT NULL DEFAULT '[]', playlist_epoch REAL, revision INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS graphics(id TEXT PRIMARY KEY, preview TEXT, program TEXT, held INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS gateways(id TEXT PRIMARY KEY, heartbeat REAL NOT NULL, source TEXT NOT NULL, profile TEXT NOT NULL, hardware_connected INTEGER NOT NULL, state TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS output_clients(id TEXT PRIMARY KEY, output TEXT NOT NULL, heartbeat REAL NOT NULL, width INTEGER NOT NULL, height INTEGER NOT NULL, revision INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY AUTOINCREMENT, at REAL NOT NULL,user_id TEXT NOT NULL, action TEXT NOT NULL, entity TEXT NOT NULL, old_value TEXT, new_value TEXT, source TEXT NOT NULL, reason TEXT NOT NULL);
